// src/components/ShopifyCollection.jsx
import React, { useEffect, useRef } from 'react';

export default function ShopifyCollection() {
    const wrapperRef = useRef(null);

    useEffect(() => {
        const wrapper = wrapperRef.current;
        if (!wrapper) return;

        // 1) Clear any previous content
        wrapper.innerHTML = '';

        // 2) Create and append the mount-point div
        const mountPoint = document.createElement('div');
        mountPoint.id = 'collection-component-1748488507848';
        wrapper.appendChild(mountPoint);

        // 3) Function to initialize the collection widget
        function initializeShopify() {
            const client = window.ShopifyBuy.buildClient({
                domain: 'pwnxmm-ws.myshopify.com',
                storefrontAccessToken: '271ea9b3291f46ee8afc6aa6503b9f7b',
            });

            window.ShopifyBuy.UI.onReady(client).then((ui) => {
                ui.createComponent('collection', {
                    id: '494103822620',
                    node: mountPoint,
                    moneyFormat: '%24%7B%7Bamount%7D%7D',
                    options: {
                        /* your options object (styles, text, cart, etc.) */
                    }
                });
            });
        }

        // 4) Load Shopify’s Buy‑Button SDK if needed
        if (window.ShopifyBuy && window.ShopifyBuy.UI) {
            // SDK already there
            initializeShopify();
        } else {
            // inject the SDK script
            const existing = document.getElementById('shopify-buy-button-script');
            if (!existing) {
                const script = document.createElement('script');
                script.id = 'shopify-buy-button-script';
                script.src = 'https://sdks.shopifycdn.com/buy-button/latest/buy-button-storefront.min.js';
                script.async = true;
                script.onload = initializeShopify;
                document.body.appendChild(script);
            } else {
                existing.onload = initializeShopify;
            }
        }

        // Cleanup on unmount (optional)
        return () => {
            // If you want to remove the script and mount-point:
            // document.body.removeChild(document.getElementById('shopify-buy-button-script'));
            // wrapper.innerHTML = '';
        };
    }, []);

    return <div ref={wrapperRef} />;
}
