import React, { useEffect, useRef, useState } from 'react';
import './HeroSection.css';
import Logo from '../images/mercedespoollogo.jpg'
import MercedesPoolLogo from "../images/mercedespoollogo.jpg";
import SprayPaint from "../images/spraypaint.jpeg"

const HeroSection = () => {
    const forwardVideoRef = useRef(null);
    const reverseVideoRef = useRef(null);
    const [isMobile, setIsMobile] = useState(false);
    const [showModal, setShowModal] = useState(true);
    const [fadeOut, setFadeOut] = useState(false);

    useEffect(() => {
        const fadeTimer = setTimeout(() => setFadeOut(true), 9000); // start fading at 4.5s
        const hideTimer = setTimeout(() => setShowModal(false), 10000); // hide at 5s
        return () => {
            clearTimeout(fadeTimer);
            clearTimeout(hideTimer);
        };
    }, []);

    const forwardVideoURL = 'https://res.cloudinary.com/duz4vhtcn/video/upload/v1747084945/vidu-video-2772905594124313_online-video-cutter.com_1_g7mfmf.mp4';
    const reversedVideoURL = 'https://res.cloudinary.com/duz4vhtcn/video/upload/e_reverse/v1747084945/vidu-video-2772905594124313_online-video-cutter.com_1_g7mfmf.mp4';
    const posterImage = 'https://res.cloudinary.com/duz4vhtcn/image/upload/v1747102947/123-1_2_vccdbf.jpg';


    useEffect(() => {
        const timer = setTimeout(() => setShowModal(false), 10000);
        return () => clearTimeout(timer);
    }, []);

    useEffect(() => {
        const checkMobile = () => {
            setIsMobile(window.innerWidth <= 845);
        };
        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);

    useEffect(() => {
        if (isMobile) return;
        const forward = forwardVideoRef.current;
        const reverse = reverseVideoRef.current;

        const playForward = () => {
            reverse.style.opacity = 0;
            forward.style.opacity = 1;
            forward.currentTime = 0;
            forward.play().catch(() => {});
        };

        const playReverse = () => {
            forward.style.opacity = 0;
            reverse.style.opacity = 1;
            reverse.currentTime = 0;
            reverse.play().catch(() => {});
        };

        forward.addEventListener('ended', playReverse);
        reverse.addEventListener('ended', playForward);
        forward.onloadeddata = () => playForward();

        return () => {
            forward.removeEventListener('ended', playReverse);
            reverse.removeEventListener('ended', playForward);
        };
    }, [isMobile]);

    return (
        <div>
        <section id="home">
            <div className="video-layer">
                {isMobile ? (
                    <img
                        src={posterImage}
                        alt="Mercedes Pools Poster"
                        className="poster-image"
                    />
                ) : (
                    <>
                        <video ref={forwardVideoRef} muted playsInline preload="auto" poster={posterImage}>
                            <source src={forwardVideoURL} type="video/mp4" />
                        </video>
                        <video ref={reverseVideoRef} muted playsInline preload="auto" style={{ opacity: 0 }}>
                            <source src={reversedVideoURL} type="video/mp4" />
                        </video>
                    </>
                )}


            </div>

            {/* Modal */}
            {showModal && (
                <div
                    className={`position-absolute p-3 transition-opacity`}
                    style={{
                        top: '50%',
                        left: '50%',
                        transform: 'translate(-50%, -50%)',
                        zIndex: 1055,
                        maxWidth: '350px',
                        width: '90%',
                        opacity: fadeOut ? 0 : 1,
                        transition: 'opacity 0.5s ease-in-out',
                    }}
                >
                    <div
                        className="modal-content text-white shadow-lg rounded"
                        style={{
                            background: 'linear-gradient(135deg, #FF7E00, #FFA500, #FFB347)',
                            border: 'none',
                            padding: '1.25rem',
                            opacity: 0.95,
                        }}
                    >
                        <div className="d-flex justify-content-center align-items-start w-100">                            <div
                            >
                                <img
                                    src={MercedesPoolLogo}
                                    alt="Mercedes Pools Logo"
                                    style={{ height: '40px', width: 'auto' }}
                                />
                            </div>
                        </div>

                        <p style={{ fontStyle: 'italic', fontSize: '0.95rem', marginBottom: '0.75rem' }}>
                            "The premier swimming pool supplier and service firm in North Texas."
                        </p>
                        <a
                            href="tel:+14693663556"
                            className="btn btn-light btn-sm w-100 fw-bold"
                        >
                            📞 Call Us Now
                        </a>
                        <small className="d-block text-white mt-2" style={{ fontSize: '0.8rem' }}>
                            CALL US (469) 366-3556
                        </small>
                    </div>

                </div>
            )}






        </section>
        <div style={{paddingLeft:'20px', paddingRight:'20px', textAlign:'center',marginTop:'20px', marginBottom:'20px'}}>
          <h1> Mercedes’ Pools™</h1>
            <p style={{ color: 'black', fontSize: '16px' }}>provides the highest standards of pool care, repair and remodeling for the discriminating homeowner. We service the entire Metroplex.
        </p> </div>
        </div>
    );
};

export default HeroSection;
